await (async(page)=>{
 const root='/Users/yunho/Documents/dcx_agent-channels-build/docs/development/channel-expansion/qa/';
 const api='http://localhost:8000',sid='s0b496d50fd7a4ec7884eb11611993f4c',out={};
 const group=()=>page.getByRole('group',{name:'유튜브 브이로그 설정',exact:true});
 const fill=async(a,b,c)=>{await group().getByLabel('키워드당 영상 수').fill(a);await group().getByLabel('최소 길이(분)',{exact:true}).fill(b);await group().getByLabel('최대 길이(분)',{exact:true}).fill(c);};
 const save=async()=>{const res=page.waitForResponse(r=>r.url().includes('/config')&&r.request().method()==='PUT');await page.getByRole('button',{name:'저장',exact:true}).click();await res;await page.getByText('저장했습니다. 수집 시작 버튼을 누르면 수집합니다.',{exact:true}).waitFor();};
 const capture=async(id)=>{await page.screenshot({path:root+id+'.png',fullPage:true});return {time:new Date().toISOString(),url:page.url(),dom:await page.locator('main').ariaSnapshot()};};
 const get=async()=>await(await page.request.get(api+'/session/'+sid)).json();
 await fill('5','2','30');await save();await page.reload();await page.getByText('고급 설정 펼치기 · 채널별 동시성 · 요청 간격 · 상한',{exact:true}).click();
 await group().waitFor();
 out['QA-E2E-002']={...await capture('QA-E2E-002'),values:await group().locator('input').evaluateAll(es=>es.map(e=>e.value)),session:await get()};
 await page.getByRole('switch',{name:'유튜브 브이로그 사용하기',exact:true}).uncheck();
 out['QA-E2E-002'].hiddenWhenOff=await group().count()===0;
 await page.getByRole('switch',{name:'유튜브 브이로그 사용하기',exact:true}).check();
 await fill('5','30','10');
 const before=await get();
 const invalid=await page.request.put(api+'/crawl/'+sid+'/config',{data:{channels:['youtube_vlog','threads','naver_kin','cook82'],youtube_vlog:{min_duration_s:1800,max_duration_s:600}}});
 out['QA-NEG-001']={...await capture('QA-NEG-001'),saveDisabled:await page.getByRole('button',{name:'저장',exact:true}).isDisabled(),startDisabled:await page.getByRole('button',{name:'목록 수집 시작',exact:true}).isDisabled(),before:before.data.crawlConfig.youtube_vlog,response:{status:invalid.status(),body:await invalid.json()},after:(await get()).data.crawlConfig.youtube_vlog};
 const zero=await page.request.put(api+'/crawl/'+sid+'/config',{data:{channels:['youtube_vlog'],youtube_vlog:{videos_per_keyword:0}}});
 out['QA-NEG-004']={time:new Date().toISOString(),url:api+'/crawl/'+sid+'/config',status:zero.status(),body:await zero.json()};
 await fill('5','0','1');await save();
 out['QA-EDGE-004']={...await capture('QA-EDGE-004'),saved:(await get()).data.crawlConfig.youtube_vlog};
 await fill('5','2','30');await save();
 for(const name of ['네이버 카페','네이버 블로그','유튜브 댓글','뽐뿌','클리앙'])await page.getByRole('switch',{name:name+' 사용하기',exact:true}).check();
 out['QA-REG-002']={...await capture('QA-REG-002')};
 await page.reload();await page.getByRole('switch',{name:'Threads 사용하기',exact:true}).waitFor();
 await page.setViewportSize({width:375,height:812});
 out['QA-EDGE-003-settings']={...await capture('QA-EDGE-003-settings'),layout:await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,tables:[...document.querySelectorAll('table')].map(t=>({text:t.innerText,width:t.scrollWidth,parentWidth:t.parentElement.clientWidth,parentScroll:t.parentElement.scrollWidth,overflow:getComputedStyle(t.parentElement).overflowX}))}))};
 const table=page.getByRole('table',{name:'수집 채널',exact:true});
 await table.evaluate(t=>{t.parentElement.scrollLeft=t.parentElement.scrollWidth;});
 out['QA-EDGE-003-settings'].scrolled=await capture('QA-EDGE-003-settings-scrolled');
 await page.setViewportSize({width:1440,height:1000});
 await page.getByRole('button',{name:'목록 수집 시작',exact:true}).click();
 await page.getByRole('heading',{name:'본문 수집 전에 키워드를 정리합니다',exact:true}).waitFor({timeout:60000});
 out.gateInitial={time:new Date().toISOString(),dom:await page.locator('main').ariaSnapshot()};
 return out;
}
)(page);
